<script>document.addEventListener('DOMContentLoaded',()=>{const service=document.getElementById('availability-service'),field=document.getElementById('slot-length-field'),input=field.querySelector('input');function toggle(){const confession=service.value==='confession';field.hidden=!confession;input.required=confession;}service.addEventListener('change',toggle);toggle();const selectAll=document.getElementById('select-all-weekdays'),days=[...document.querySelectorAll('#weekday-options input[name="weekdays[]"]')];if(selectAll){function updateButton(){selectAll.textContent=days.length&&days.every(day=>day.checked)?selectAll.dataset.clearAll:selectAll.dataset.selectAll;}selectAll.addEventListener('click',()=>{const checkAll=!days.every(day=>day.checked);days.forEach(day=>day.checked=checkAll);updateButton();});days.forEach(day=>day.addEventListener('change',updateButton));updateButton();}});</script>
